class IncorrectCellId(Exception):
    """Raised when UE is attached to different cell than desired"""
    pass


class MissingReservedUE(Exception):
    """ Raised when no UE was reserved in test setup (UE Reservation keyword was skipped) """
    pass


class IncorrectDataTransferDirection(Exception):
    """ Raised when given data transfer direction is different from defined """
    pass


class UeNetworkModeMissing(Exception):
    """ Raised when ue_network_modes parameter is missing and gnbCuType is SA+NSA """
    pass


class UnrecognizedUeNetworkMode(Exception):
    """ Raised when one of network modes is not supported """
    pass


class ConflictingUeNetworkModes(Exception):
    """
    Raised when one of the network modes in operating in
    SA and other in NSA which is not supported yet
    """
    pass


class PingStatisticsNotFound(Exception):
    """
    Raised when ping statistics could not be found
    """
    pass


class PingExecutionFailed(Exception):
    """
    Raised when ping execution failed
    """
    pass


class PingValidationFailed(Exception):
    """
    Raised when ping validation failed
    """
    pass
